package com.linkforge.config;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.info.BuildProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Fixes the springdoc info block instead of the default placeholder; the version comes
 * from META-INF/build-info.properties (generated by the boot plugin), falling back to
 * "dev" when running from an IDE without a build.
 */
@Configuration
public class OpenApiConfig {

    @Bean
    public OpenAPI linkForgeOpenApi(ObjectProvider<BuildProperties> buildProperties) {
        BuildProperties build = buildProperties.getIfAvailable();
        return new OpenAPI().info(new Info()
                .title("LinkForge")
                .version(build != null ? build.getVersion() : "dev")
                .description("多租户短链 + 访问分析后端（短链创建、302 跳转、点击双写聚合）"));
    }
}
